// Verifies the request really came from Convex and is fresh. Rejections never reveal which check failed.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;

const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET is not set'); // misconfiguration: fail loudly so Convex retries and alerts fire

const headers = $input.first().json.headers;
const timestamp = headers['x-lendloop-timestamp'] ?? '';
const signature = headers['x-lendloop-signature'] ?? '';
const reject = (reason) => [{ json: { action: 'reject', reason } }];

if (!/^\d+$/.test(timestamp)) return reject('missing timestamp');
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > MAX_SKEW_SECONDS) return reject('stale timestamp (possible replay)');

let raw;
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch {
  return reject('missing body');
}

// Signature is over the raw bytes Convex sent, not re-serialized JSON.
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest('hex');
const given = Buffer.from(signature);
const wanted = Buffer.from(expected);
if (given.length !== wanted.length || !crypto.timingSafeEqual(given, wanted)) return reject('bad signature');

const payload = JSON.parse(raw);
if (headers['x-lendloop-event-id'] !== payload.eventId) return reject('event id mismatch');

const seen = $getWorkflowStaticData('global').seen ?? {};
if (seen[payload.eventId]) return [{ json: { action: 'duplicate', eventId: payload.eventId } }];

return [{ json: { action: 'deliver', ...payload } }];

const p = $input.first().json;
const who = p.otherParty.firstName;
const tool = p.tool.name;
const dates = p.loan.startDate === p.loan.endDate ? p.loan.startDate : `${p.loan.startDate} to ${p.loan.endDate}`;

const templates = {
  requested: [
    `${who} wants to borrow your ${tool}`,
    `${who} asked to borrow your ${tool} for ${dates}.` +
      (p.loan.message ? `\n\nTheir message: "${p.loan.message}"` : '') +
      `\n\nApprove or decline it under Incoming in LendLoop.`,
  ],
  approved: [`${who} approved your request`, `Good news: ${who} approved your request to borrow the ${tool} for ${dates}. Arrange the pickup with them.`],
  declined: [`Your request for the ${tool} was declined`, `${who} can't lend the ${tool} for ${dates}. Try other dates or another tool on LendLoop.`],
  cancelled: [`${who} cancelled their request`, `${who} no longer needs your ${tool} for ${dates}. Nothing to do on your side.`],
  returned: [`Thanks for returning the ${tool}`, `${who} marked the ${tool} as returned. Thanks for borrowing responsibly!`],
  tool_removed: [`The ${tool} is no longer available`, `The ${tool} was removed from LendLoop, so your request for ${dates} was closed.`],
};

const template = templates[p.event];
if (!template) throw new Error(`Unknown event: ${p.event}`);

return [{
  json: {
    eventId: p.eventId,
    event: p.event,
    to: p.recipient.email,
    subject: `LendLoop: ${template[0]}`,
    text: `Hi ${p.recipient.firstName},\n\n${template[1]}\n\n- LendLoop`,
  },
}];

// Only reached after a successful send, so a failed send is NOT marked and Convex's retry gets through.
const store = $getWorkflowStaticData('global');
store.seen = store.seen ?? {};
const now = Date.now();
const WEEK_MS = 7 * 24 * 60 * 60 * 1000;
for (const [id, at] of Object.entries(store.seen)) if (now - at > WEEK_MS) delete store.seen[id];
// Send Email's output doesn't carry eventId, so read it from the step that built the message.
store.seen[$('Compose message').first().json.eventId] = now;
return $input.all();
